#include <iostream>
#include <sstream>
#include <cstring>
#include <iomanip>

struct ClientData {
    int acctNum{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

void insertRecord(std::iostream& stream, int acct, const char* last, const char* first, double bal) {
    std::streamoff offset = static_cast<std::streamoff>((acct - 1) * sizeof(ClientData));
    stream.seekg(offset);
    ClientData current{};
    stream.read(reinterpret_cast<char*>(&current), sizeof(ClientData));

    if (current.acctNum != 0) {
        std::cout << "Account #" << acct << " already contains information.\n";
        return;
    }

    ClientData newClient{acct, "", "", bal};
    std::strncpy(newClient.lastName, last, sizeof(newClient.lastName) - 1);
    std::strncpy(newClient.firstName, first, sizeof(newClient.firstName) - 1);

    stream.seekp(offset);
    stream.write(reinterpret_cast<const char*>(&newClient), sizeof(ClientData));
    std::cout << "Account #" << acct << " inserted.\n";
}

void deleteRecord(std::iostream& stream, int acct) {
    std::streamoff offset = static_cast<std::streamoff>((acct - 1) * sizeof(ClientData));
    stream.seekg(offset);
    ClientData current{};
    stream.read(reinterpret_cast<char*>(&current), sizeof(ClientData));

    if (current.acctNum == 0) {
        std::cout << "Account " << acct << " does not exist.\n";
        return;
    }

    ClientData blankClient{0, "", "", 0.0};
    stream.seekp(offset);
    stream.write(reinterpret_cast<const char*>(&blankClient), sizeof(ClientData));
    std::cout << "Account " << acct << " deleted.\n";
}

int main() {
    std::stringstream storage(std::ios::in | std::ios::out | std::ios::binary);
    ClientData blank{};
    for (int i = 0; i < 5; ++i) {
        storage.write(reinterpret_cast<const char*>(&blank), sizeof(ClientData));
    }

    insertRecord(storage, 3, "Smith", "John", 245.50);
    insertRecord(storage, 3, "Doe", "Jane", 100.00);
    deleteRecord(storage, 3);
    deleteRecord(storage, 3);

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

class SafeRecordStore {
private:
    std::stringstream stream;
public:
    SafeRecordStore() : stream(std::ios::in | std::ios::out | std::ios::binary) {}

    // FIO04-C & FIO07-C compliant seek
    bool secureSeek(std::streamoff pos) {
        stream.clear(); // Clear any previous error bits
        stream.seekg(pos, std::ios::beg);
        stream.seekp(pos, std::ios::beg);
        return !stream.fail();
    }

    bool writeData(const std::string& record) {
        if (!stream.good()) return false;
        stream << record << "\n";
        return !stream.fail(); // FIO04-C check write status
    }

    std::string readNextLine() {
        std::string line;
        if (std::getline(stream, line)) {
            return line;
        }
        return "<EOF_OR_ERROR>";
    }
};

int main() {
    SafeRecordStore store;

    if (store.writeData("ACCT101: 500.00")) {
        std::cout << "Write successful.\n";
    }

    if (store.secureSeek(0)) { // Equivalent to safe rewind
        std::cout << "Seek successful: " << store.readNextLine() << "\n";
    }

    return 0;
}
